(7217416, 1112445, 173844, '<td valign="top">Beautifully done flower image that uses monotone to allow the symmetry to come into its own.  The petals serve as backdrop for the inner delicacy (stamens, etc.).  The idea of color is subtly inherent since we all know about flowers.</td>', 'Beautifully done flower image that uses monotone to allow the symmetry to come into its own.  The petals serve as backdrop for the inner delicacy (stamens, etc.).  The idea of color is subtly inherent since we all know about flowers.', '2014-05-16 11:46:31.000000', NULL, 1),
(7217419, 1112474, 173844, '<td valign="top">It''s busy, but packs in tons of various and interesting symmetries.  The fun is in searching them out.  The woman ascending the staircase is the perfect asymmetrical finishing touch.</td>', 'It''s busy, but packs in tons of various and interesting symmetries.  The fun is in searching them out.  The woman ascending the staircase is the perfect asymmetrical finishing touch.', '2014-05-16 11:53:44.000000', NULL, 1),
(7217442, 1112409, 38921, '<td valign="top">Very nice capture. I would prefer to eyes to have been in sharp focus as well.</td>', 'Very nice capture. I would prefer to eyes to have been in sharp focus as well.', '2014-05-16 13:21:09.000000', NULL, 1),
(7217448, 1112166, 15305, '<td valign="top">My favorite for the challenge, I see a Blue Ribbon in your near future!!! Congratulations and thanks for such a wonderful image!!!</td>', 'My favorite for the challenge, I see a Blue Ribbon in your near future!!! Congratulations and thanks for such a wonderful image!!!', '2014-05-16 13:44:10.000000', NULL, 1),
(7217484, 1112404, 173844, '<td valign="top">Crisp and ominous, nice spread of tones contrasting those regimented in the structure and those swirling in the sky.</td>', 'Crisp and ominous, nice spread of tones contrasting those regimented in the structure and those swirling in the sky.', '2014-05-16 15:22:26.000000', NULL, 1),
