(7217489, 1112476, 173844, '<td valign="top">Nice approximate symmetry, which is fine.  What if the people were to be cut off at about the waist to isolate the symmetry and forego the busy background?  Just a thought.</td>', 'Nice approximate symmetry, which is fine.  What if the people were to be cut off at about the waist to isolate the symmetry and forego the busy background?  Just a thought.', '2014-05-16 15:29:36.000000', NULL, 1),
(7217491, 1112477, 173844, '<td valign="top">Very pretty capture.  Those translucent feathers make a lovely effect.</td>', 'Very pretty capture.  Those translucent feathers make a lovely effect.', '2014-05-16 15:33:21.000000', NULL, 1),
(7217494, 1112397, 173844, '<td valign="top">Fine illustration of the multiple universes theory.  Very attractive depth of field. Several mugs of this and the bicameral brain will be on the wane.</td>', 'Fine illustration of the multiple universes theory.  Very attractive depth of field. Several mugs of this and the bicameral brain will be on the wane.', '2014-05-16 15:39:01.000000', NULL, 1),
