(7217498, 1112461, 173844, '<td valign="top">Nice shimmery reflection.  I feel a desire to see the top of the central tree, but that''s a stylistic matter.</td>', 'Nice shimmery reflection.  I feel a desire to see the top of the central tree, but that''s a stylistic matter.', '2014-05-16 15:49:01.000000', NULL, 1),
(7217509, 1112249, 173844, '<td valign="top">Dramatically evocative. How this reflection is acquired is beyond me, but it''s so startling and enjoyable that it becomes unnecessary to fathom.  What an unusual image, and I happen to like it a lot.</td>', 'Dramatically evocative. How this reflection is acquired is beyond me, but it''s so startling and enjoyable that it becomes unnecessary to fathom.  What an unusual image, and I happen to like it a lot.', '2014-05-16 16:45:59.000000', NULL, 1),
(7217510, 1112447, 173844, '<td valign="top">Quirky image, gorgeous colors, fine composition, offhand symmetry.  Way to make the most of this challenge.  Simple, engaging, terrific.</td>', 'Quirky image, gorgeous colors, fine composition, offhand symmetry.  Way to make the most of this challenge.  Simple, engaging, terrific.', '2014-05-16 16:49:48.000000', NULL, 1),
(7217511, 1112266, 173844, '<td valign="top">Pretty, simple image that elegantly fills the frame.  Lovely bokeh.</td>', 'Pretty, simple image that elegantly fills the frame.  Lovely bokeh.', '2014-05-16 16:52:09.000000', NULL, 1),
(7217512, 1112369, 173844, '<td valign="top">Nice symmetry that looks better for its lack of perfection.  It''s like a portal deep in space; don''t forget the duct tape.</td>', 'Nice symmetry that looks better for its lack of perfection.  It''s like a portal deep in space; don''t forget the duct tape.', '2014-05-16 16:55:27.000000', NULL, 1),
