(7217790, 1112225, 30049, '<td valign="top">Wipe out the left and right thirds and switch this composition to a portrait layout.  How''s it look?  IMO it would have been a top contender.  As is, it''s fine, but not fantastic.  You lost the story in the surrounding elements.</td>', 'Wipe out the left and right thirds and switch this composition to a portrait layout.  How''s it look?  IMO it would have been a top contender.  As is, it''s fine, but not fantastic.  You lost the story in the surrounding elements.', '2014-05-17 23:05:23.000000', NULL, 1),
(7217792, 1112377, 30049, '<td valign="top">Yikes!  :-D  In your face.  I like it.  Want to love it ... lost a tad in the eyes.  If those were tack sharp and crisp (without noise) this photo would be for sure on the front page on rollover.  As is, I predict Top 20.  Good luck!</td>', 'Yikes!  :-D  In your face.  I like it.  Want to love it ... lost a tad in the eyes.  If those were tack sharp and crisp (without noise) this photo would be for sure on the front page on rollover.  As is, I predict Top 20.  Good luck!', '2014-05-17 23:07:36.000000', NULL, 1),
(7217793, 1111909, 30049, '<td valign="top">Too much going on here I think.  Not really a strong story.</td>', 'Too much going on here I think.  Not really a strong story.', '2014-05-17 23:08:39.000000', NULL, 1),
