(7217796, 1112427, 30049, '<td valign="top">Symmetry from a side view.  Unique take.  Bet they put on a good show!</td>', 'Symmetry from a side view.  Unique take.  Bet they put on a good show!', '2014-05-17 23:13:01.000000', NULL, 1),
(7217797, 1112436, 30049, '<td valign="top">Funny how the lights aren''t on on the right side, but are on the left.  :-)  Very dramatic with the toning and that fantastic sky.  Well done.</td>', 'Funny how the lights aren''t on on the right side, but are on the left.  :-)  Very dramatic with the toning and that fantastic sky.  Well done.', '2014-05-17 23:15:08.000000', NULL, 1),
