(7218010, 1112371, 152252, '<td valign="top">One of my top choices. I love how the sky "connects". Beautiful scenery.</td>', 'One of my top choices. I love how the sky "connects". Beautiful scenery.', '2014-05-18 15:45:44.000000', NULL, 1),
(7218013, 1112080, 83313, '<td valign="top">I''m not terribly thrilled with the image quality. Fuzzy and low contrast. Not sure if that is intentional or not. However, this scene has a VERY strong connection with me, as I''d much rather go ride my bike than deal with the yardwork. Yardwork, <i>BLEGH</i>.<br/> <br/>An 8 for the strong personal impact this image has with me.</td>', 'I''m not terribly thrilled with the image quality. Fuzzy and low contrast. Not sure if that is intentional or not. However, this scene has a VERY strong connection with me, as I''d much rather go ride my bike than deal with the yardwork. Yardwork, BLEGH. An 8 for the strong personal impact this image has with me.', '2014-05-18 16:03:28.000000', NULL, 1),
(7218014, 1112122, 83313, '<td valign="top">Almost looks obscene.</td>', 'Almost looks obscene.', '2014-05-18 16:04:18.000000', NULL, 1),
(7218015, 1112409, 83313, '<td valign="top">Nice detail in this. I know that even with a big lens, you need some skill to get close enough for such a shot. A lot in common between hunting with a camera and with a gun. (But you can hunt anything with a camera all year long)</td>', 'Nice detail in this. I know that even with a big lens, you need some skill to get close enough for such a shot. A lot in common between hunting with a camera and with a gun. (But you can hunt anything with a camera all year long)', '2014-05-18 16:06:05.000000', NULL, 1),
